operations.describe:
{
  "name": "project-cleanup-confirm",
  "domain": "projects",
  "summary": "Move the chosen documents to the Papierkorb",
  "description": "Puts the documents the person chose (`documentIds`) into the Papierkorb, all or nothing; they can be restored for 14 days. `proposedIds` is what project-cleanup-propose suggested and `aiUsed` says whether a proposal was used. Never send ids the person did not approve.",
  "annotations": {
    "title": "Move the chosen documents to the Papierkorb",
    "readOnlyHint": false,
    "destructiveHint": true,
    "idempotentHint": false,
    "openWorldHint": false
  },
  "sensitivity": null,
  "inputSchema": {
    "type": "object",
    "properties": {
      "params": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The project id, from project-list."
          }
        },
        "required": [
          "id"
        ],
        "additionalProperties": true
      },
      "body": {
        "type": "object",
        "properties": {
          "documentIds": {
            "type": "array",
            "items": {
              "type": "string",
              "format": "uuid"
            },
            "maxItems": 2000
          },
          "proposedIds": {
            "type": "array",
            "items": {
              "type": "string",
              "format": "uuid"
            },
            "maxItems": 2000
          },
          "aiUsed": {
            "type": "boolean"
          }
        },
        "required": [
          "documentIds",
          "proposedIds",
          "aiUsed"
        ],
        "additionalProperties": false
      },
      "ifMatch": {
        "type": "string",
        "minLength": 1,
        "maxLength": 256,
        "description": "Sent as If-Match: the version you read (the project profile: its profileVersion). A write over a newer version is refused; read again, then retry."
      }
    },
    "additionalProperties": false,
    "required": [
      "params",
      "body"
    ]
  }
}

{
  "name": "project-cleanup-propose",
  "domain": "projects",
  "summary": "Have Piloti propose what to clear out",
  "description": "Before a project closes („Ausmisten\"): Piloti proposes which documents the finished project no longer needs, among those the person may read and write. Starts a paid model call, so call it once. Nothing is removed. Show the proposal to the person, then send their choice with project-cleanup-confirm.",
  "annotations": {
    "title": "Have Piloti propose what to clear out",
    "readOnlyHint": true,
    "destructiveHint": false,
    "idempotentHint": true,
    "openWorldHint": false
  },
  "sensitivity": null,
  "inputSchema": {
    "type": "object",
    "properties": {
      "params": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The project id, from project-list."
          }
        },
        "required": [
