        ],
        "additionalProperties": true
      },
      "body": {
        "type": "object",
        "properties": {
          "locale": {
            "type": "string",
            "enum": [
              "de",
              "en"
            ]
          }
        },
        "required": [
          "locale"
        ],
        "additionalProperties": false
      }
    },
    "additionalProperties": false,
    "required": [
      "params",
      "body"
    ]
  }
}

{
  "name": "project-consistency-check",
  "domain": "projects",
  "summary": "Check free-text answers for contradictions",
  "description": "Asks the backend model whether the intake’s free-text answers contradict the structured answers (passed as context). Best effort: always answers `{ findings, error? }`, and an error means proceed. Call before saving a profile edited in free text.",
  "annotations": {
    "title": "Check free-text answers for contradictions",
    "readOnlyHint": true,
    "destructiveHint": false,
    "idempotentHint": true,
    "openWorldHint": false
  },
  "sensitivity": null,
  "inputSchema": {
    "type": "object",
    "properties": {
      "params": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The project id, from project-list."
          }
        },
        "required": [
          "id"
        ],
        "additionalProperties": true
      },
      "body": {
        "type": "object",
        "properties": {
          "freeText": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "field": {
                  "type": "string"
                },
                "value": {
                  "type": "string"
                }
              },
              "required": [
                "field",
                "value"
              ],
              "additionalProperties": true
            },
            "maxItems": 50
          },
          "structured": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "field": {
                  "type": "string"
                },
                "value": {
                  "type": "string"
                }
              },
              "required": [
                "field",
                "value"
              ],
              "additionalProperties": true
            },
            "maxItems": 200
          },
          "locale": {
            "type": "string"
          }
        },
        "required": [
          "freeText"
        ],
        "additionalProperties": true
      }
    },
    "additionalProperties": false,
    "required": [
