{
  "name": "project-create",
  "domain": "projects",
  "summary": "Create a project",
  "description": "Creates a project in the organization and returns it with its id. Give a name; optionally the address (a geocoder hit as `location`, or typed `address`), a description, and `setup`: `piloti` (default) has Piloti read the documents afterwards, `self` leaves the profile to the intake wizard. To add a past project as a reference, pass `closing` with the outcome and months. Call project-same-address-list first to avoid a duplicate. Next: upload documents, then project-intake-get to follow the reading.",
  "annotations": {
    "title": "Create a project",
    "readOnlyHint": false,
    "destructiveHint": false,
    "idempotentHint": false,
    "openWorldHint": false
  },
  "sensitivity": null,
  "inputSchema": {
    "type": "object",
    "properties": {
      "body": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "minLength": 1,
            "maxLength": 255
          },
          "closing": {
            "type": "object",
            "properties": {
              "outcome": {
                "type": "string",
                "enum": [
                  "completed",
                  "cancelled"
                ]
              },
              "endedOn": {
                "type": "string"
              },
              "startedOn": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ]
              }
            },
            "required": [
              "outcome",
              "endedOn",
              "startedOn"
            ],
            "additionalProperties": false
          },
          "setup": {
            "type": "string",
            "enum": [
              "piloti",
              "self"
            ]
          },
          "description": {
            "type": "string",
            "maxLength": 500
          },
          "location": {
            "type": "object",
            "properties": {
              "label": {
                "type": "string",
                "minLength": 1
              },
              "lat": {
                "type": "number"
              },
              "lon": {
                "type": "number"
              },
              "country": {
                "const": "at"
              },
              "federalState": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "state": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "municipality": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "postcode": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "kind": {
                "type": "string",
                "enum": [
                  "address",
                  "street",
                  "place"
                ]
              }
            },
            "required": [
              "label",
              "lat",
              "lon",
              "country",
              "federalState",
              "state",
              "municipality",
              "postcode",
              "kind"
            ],
            "additionalProperties": true
          },
          "address": {
            "type": "string",
            "maxLength": 200
          },
          "federalState": {
            "type": "string"
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      },
      "ifMatch": {
        "type": "string",
        "minLength": 1,
        "maxLength": 256,
        "description": "Sent as If-Match: the version you read (the project profile: its profileVersion). A write over a newer version is refused; read again, then retry."
      }
    },
    "additionalProperties": false,
    "required": [
      "body"
    ]
  }
}

