{
  "name": "project-intake-decide",
  "domain": "projects",
  "summary": "Decide on intake suggestions",
  "description": "Applies decisions on what Piloti read: `confirm` writes a suggestion (or the alternative at `alternativeIndex`), `dismiss` removes it, `answer` writes the person’s own value, `unknown` records the key as not known. Keys come from project-intake-get. Answers one result per decision, in order, and the intake after them.",
  "annotations": {
    "title": "Decide on intake suggestions",
    "readOnlyHint": false,
    "destructiveHint": false,
    "idempotentHint": false,
    "openWorldHint": false
  },
  "sensitivity": null,
  "inputSchema": {
    "type": "object",
    "properties": {
      "params": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The project id, from project-list."
          }
        },
        "required": [
          "id"
        ],
        "additionalProperties": true
      },
      "body": {
        "type": "object",
        "properties": {
          "decisions": {
            "type": "array",
            "items": {
              "oneOf": [
                {
                  "type": "object",
                  "properties": {
                    "key": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 200
                    },
                    "action": {
                      "const": "confirm"
                    },
                    "alternativeIndex": {
                      "type": "integer"
                    }
                  },
                  "required": [
                    "key",
                    "action"
                  ],
                  "additionalProperties": false
                },
                {
                  "type": "object",
                  "properties": {
                    "key": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 200
                    },
                    "action": {
                      "const": "dismiss"
                    },
                    "alternativeIndex": {
                      "type": "integer"
                    }
                  },
                  "required": [
                    "key",
                    "action"
                  ],
                  "additionalProperties": false
                },
                {
                  "type": "object",
                  "properties": {
                    "key": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 200
                    },
                    "action": {
                      "const": "answer"
                    },
                    "value": {
                      "anyOf": [
                        {
                          "type": "string"
                        },
                        {
                          "type": "number"
                        },
                        {
                          "type": "boolean"
                        },
                        {
                          "type": "array",
                          "items": {
                            "type": "string"
                          }
                        },
                        {
                          "type": "null"
                        }
                      ]
                    }
                  },
                  "required": [
                    "key",
                    "action",
                    "value"
                  ],
                  "additionalProperties": false
                },
                {
                  "type": "object",
                  "properties": {
                    "key": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 200
                    },
                    "action": {
                      "const": "unknown"
                    }
                  },
                  "required": [
                    "key",
                    "action"
                  ],
                  "additionalProperties": false
                }
              ],
              "discriminator": {
                "propertyName": "action"
              }
            },
            "maxItems": 60
          }
        },
        "required": [
          "decisions"
        ],
        "additionalProperties": false
      },
      "ifMatch": {
        "type": "string",
        "minLength": 1,
        "maxLength": 256,
        "description": "Sent as If-Match: the version you read (the project profile: its profileVersion). A write over a newer version is refused; read again, then retry."
      }
    },
    "additionalProperties": false,
    "required": [
      "params",
      "body"
    ]
  }
}

